-- Additive Strength Index schema. No production thresholds are approved or seeded.
PRAGMA foreign_keys=ON;
CREATE TABLE mw_principals(id TEXT PRIMARY KEY, subject TEXT NOT NULL UNIQUE, role TEXT NOT NULL CHECK(role IN ('athlete','reviewer','admin')), active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE mw_profiles(seq INTEGER PRIMARY KEY AUTOINCREMENT,id TEXT NOT NULL UNIQUE, athlete_id TEXT NOT NULL REFERENCES mw_principals(id), data TEXT NOT NULL CHECK(json_valid(data)), reason TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX mw_profiles_owner ON mw_profiles(athlete_id,seq);
CREATE TABLE mw_disciplines(id TEXT PRIMARY KEY,name TEXT NOT NULL UNIQUE);
CREATE TABLE mw_rank_definitions(id TEXT PRIMARY KEY, ordinal INTEGER NOT NULL UNIQUE CHECK(ordinal BETWEEN 1 AND 9), name TEXT NOT NULL, icon TEXT NOT NULL);
CREATE TABLE mw_rulebooks(id TEXT PRIMARY KEY, discipline TEXT NOT NULL REFERENCES mw_disciplines(id), data TEXT NOT NULL CHECK(json_valid(data)), digest TEXT NOT NULL, author_id TEXT NOT NULL REFERENCES mw_principals(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE mw_models(id TEXT PRIMARY KEY, discipline TEXT NOT NULL REFERENCES mw_disciplines(id), rulebook_id TEXT NOT NULL REFERENCES mw_rulebooks(id), data TEXT NOT NULL CHECK(json_valid(data)), digest TEXT NOT NULL, author_id TEXT NOT NULL REFERENCES mw_principals(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE mw_publications(seq INTEGER PRIMARY KEY AUTOINCREMENT,kind TEXT NOT NULL CHECK(kind IN ('model','rulebook')), version_id TEXT NOT NULL, actor_id TEXT NOT NULL REFERENCES mw_principals(id), reason TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(kind,version_id));
CREATE TABLE mw_performances(seq INTEGER PRIMARY KEY AUTOINCREMENT,id TEXT NOT NULL UNIQUE, athlete_id TEXT NOT NULL REFERENCES mw_principals(id), profile_id TEXT NOT NULL REFERENCES mw_profiles(id), discipline TEXT NOT NULL REFERENCES mw_disciplines(id), rulebook_id TEXT NOT NULL REFERENCES mw_rulebooks(id), data TEXT NOT NULL CHECK(json_valid(data)), correction_of TEXT REFERENCES mw_performances(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX mw_performances_owner ON mw_performances(athlete_id,discipline,seq);
CREATE TABLE mw_evidence(id TEXT PRIMARY KEY,performance_id TEXT NOT NULL REFERENCES mw_performances(id), athlete_id TEXT NOT NULL REFERENCES mw_principals(id), object_key TEXT NOT NULL UNIQUE, sha256 TEXT NOT NULL, bytes INTEGER NOT NULL CHECK(bytes>0 AND bytes<=20971520), mime TEXT NOT NULL CHECK(mime='video/mp4'), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE mw_reviews(seq INTEGER PRIMARY KEY AUTOINCREMENT,id TEXT NOT NULL UNIQUE,performance_id TEXT NOT NULL REFERENCES mw_performances(id), evidence_id TEXT NOT NULL REFERENCES mw_evidence(id), reviewer_id TEXT NOT NULL REFERENCES mw_principals(id), rulebook_id TEXT NOT NULL REFERENCES mw_rulebooks(id), state TEXT NOT NULL CHECK(state IN ('pending','approved','rejected','flagged')), expected_revision INTEGER NOT NULL CHECK(expected_revision>=0), revision INTEGER NOT NULL CHECK(revision=expected_revision+1), checks TEXT NOT NULL CHECK(json_valid(checks)), reason TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(performance_id,revision));
CREATE TABLE mw_results(seq INTEGER PRIMARY KEY AUTOINCREMENT,id TEXT NOT NULL UNIQUE,performance_id TEXT NOT NULL REFERENCES mw_performances(id), athlete_id TEXT NOT NULL REFERENCES mw_principals(id), profile_id TEXT NOT NULL REFERENCES mw_profiles(id), model_id TEXT NOT NULL REFERENCES mw_models(id), rulebook_id TEXT NOT NULL REFERENCES mw_rulebooks(id), kind TEXT NOT NULL CHECK(kind IN ('submission','reassessment','review','profile-scenario')), data TEXT NOT NULL CHECK(json_valid(data)), actor_id TEXT NOT NULL REFERENCES mw_principals(id), reason TEXT NOT NULL, engine_version TEXT NOT NULL DEFAULT 'strength-engine-1', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX mw_results_lookup ON mw_results(athlete_id,performance_id,model_id,seq);
CREATE TABLE mw_rank_history(seq INTEGER PRIMARY KEY AUTOINCREMENT,result_id TEXT NOT NULL REFERENCES mw_results(id), athlete_id TEXT NOT NULL REFERENCES mw_principals(id), discipline TEXT NOT NULL REFERENCES mw_disciplines(id), event TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE mw_audit(seq INTEGER PRIMARY KEY AUTOINCREMENT,id TEXT NOT NULL UNIQUE,actor_id TEXT REFERENCES mw_principals(id), action TEXT NOT NULL, target TEXT NOT NULL, outcome TEXT NOT NULL, detail TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE mw_rate_limits(actor_id TEXT PRIMARY KEY REFERENCES mw_principals(id),window INTEGER NOT NULL,attempts INTEGER NOT NULL);
CREATE TRIGGER mw_publication_guard BEFORE INSERT ON mw_publications BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM mw_principals WHERE id=NEW.actor_id AND active=1 AND role='admin') THEN RAISE(ABORT,'admin-required') END;
 SELECT CASE WHEN NEW.kind='model' AND NOT EXISTS(SELECT 1 FROM mw_models WHERE id=NEW.version_id AND author_id<>NEW.actor_id AND json_extract(data,'$.purpose')='production' AND json_array_length(data,'$.categories')>0) THEN RAISE(ABORT,'invalid-or-self-publication') END;
 SELECT CASE WHEN NEW.kind='rulebook' AND NOT EXISTS(SELECT 1 FROM mw_rulebooks WHERE id=NEW.version_id AND author_id<>NEW.actor_id) THEN RAISE(ABORT,'invalid-or-self-publication') END;
END;
CREATE TRIGGER mw_review_guard BEFORE INSERT ON mw_reviews BEGIN
 SELECT CASE WHEN NEW.expected_revision<>COALESCE((SELECT MAX(revision) FROM mw_reviews WHERE performance_id=NEW.performance_id),0) THEN RAISE(ABORT,'stale-review') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM mw_evidence WHERE id=NEW.evidence_id AND performance_id=NEW.performance_id) THEN RAISE(ABORT,'wrong-evidence') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM mw_performances WHERE id=NEW.performance_id AND rulebook_id=NEW.rulebook_id) THEN RAISE(ABORT,'wrong-rulebook') END;
 SELECT CASE WHEN NEW.state<>'pending' AND NOT EXISTS(SELECT 1 FROM mw_principals WHERE id=NEW.reviewer_id AND active=1 AND role IN ('reviewer','admin')) THEN RAISE(ABORT,'reviewer-required') END;
 SELECT CASE WHEN NEW.state='approved' AND EXISTS(SELECT 1 FROM mw_performances WHERE id=NEW.performance_id AND athlete_id=NEW.reviewer_id) THEN RAISE(ABORT,'self-approval-forbidden') END;
 SELECT CASE WHEN NEW.state='approved' AND NOT EXISTS(SELECT 1 FROM mw_publications WHERE kind='rulebook' AND version_id=NEW.rulebook_id) THEN RAISE(ABORT,'draft-rulebook') END;
END;
CREATE TRIGGER mw_evidence_owner BEFORE INSERT ON mw_evidence BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM mw_performances WHERE id=NEW.performance_id AND athlete_id=NEW.athlete_id) THEN RAISE(ABORT,'wrong-evidence-owner') END;
END;
CREATE TRIGGER mw_performance_owner BEFORE INSERT ON mw_performances BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM mw_profiles WHERE id=NEW.profile_id AND athlete_id=NEW.athlete_id) THEN RAISE(ABORT,'wrong-profile-owner') END;
 SELECT CASE WHEN NEW.correction_of IS NOT NULL AND NOT EXISTS(SELECT 1 FROM mw_performances WHERE id=NEW.correction_of AND athlete_id=NEW.athlete_id AND discipline=NEW.discipline) THEN RAISE(ABORT,'invalid-correction') END;
END;
CREATE TRIGGER mw_profiles_no_update BEFORE UPDATE ON mw_profiles BEGIN SELECT RAISE(ABORT,'append-only-record'); END;
CREATE TRIGGER mw_profiles_no_delete BEFORE DELETE ON mw_profiles BEGIN SELECT RAISE(ABORT,'append-only-record'); END;
CREATE TRIGGER mw_rulebooks_no_update BEFORE UPDATE ON mw_rulebooks BEGIN SELECT RAISE(ABORT,'append-only-record'); END;
CREATE TRIGGER mw_rulebooks_no_delete BEFORE DELETE ON mw_rulebooks BEGIN SELECT RAISE(ABORT,'append-only-record'); END;
CREATE TRIGGER mw_models_no_update BEFORE UPDATE ON mw_models BEGIN SELECT RAISE(ABORT,'append-only-record'); END;
CREATE TRIGGER mw_models_no_delete BEFORE DELETE ON mw_models BEGIN SELECT RAISE(ABORT,'append-only-record'); END;
CREATE TRIGGER mw_publications_no_update BEFORE UPDATE ON mw_publications BEGIN SELECT RAISE(ABORT,'append-only-record'); END;
CREATE TRIGGER mw_publications_no_delete BEFORE DELETE ON mw_publications BEGIN SELECT RAISE(ABORT,'append-only-record'); END;
CREATE TRIGGER mw_performances_no_update BEFORE UPDATE ON mw_performances BEGIN SELECT RAISE(ABORT,'append-only-record'); END;
CREATE TRIGGER mw_performances_no_delete BEFORE DELETE ON mw_performances BEGIN SELECT RAISE(ABORT,'append-only-record'); END;
CREATE TRIGGER mw_evidence_no_update BEFORE UPDATE ON mw_evidence BEGIN SELECT RAISE(ABORT,'append-only-record'); END;
CREATE TRIGGER mw_evidence_no_delete BEFORE DELETE ON mw_evidence BEGIN SELECT RAISE(ABORT,'append-only-record'); END;
CREATE TRIGGER mw_reviews_no_update BEFORE UPDATE ON mw_reviews BEGIN SELECT RAISE(ABORT,'append-only-record'); END;
CREATE TRIGGER mw_reviews_no_delete BEFORE DELETE ON mw_reviews BEGIN SELECT RAISE(ABORT,'append-only-record'); END;
CREATE TRIGGER mw_results_no_update BEFORE UPDATE ON mw_results BEGIN SELECT RAISE(ABORT,'append-only-record'); END;
CREATE TRIGGER mw_results_no_delete BEFORE DELETE ON mw_results BEGIN SELECT RAISE(ABORT,'append-only-record'); END;
CREATE TRIGGER mw_rank_history_no_update BEFORE UPDATE ON mw_rank_history BEGIN SELECT RAISE(ABORT,'append-only-record'); END;
CREATE TRIGGER mw_rank_history_no_delete BEFORE DELETE ON mw_rank_history BEGIN SELECT RAISE(ABORT,'append-only-record'); END;
CREATE TRIGGER mw_audit_no_update BEFORE UPDATE ON mw_audit BEGIN SELECT RAISE(ABORT,'append-only-record'); END;
CREATE TRIGGER mw_audit_no_delete BEFORE DELETE ON mw_audit BEGIN SELECT RAISE(ABORT,'append-only-record'); END;
