INSERT INTO mw_rulebooks(id,discipline,data,digest,author_id) VALUES('bench-standard-draft-1','bench','{"checks":[{"id":"setup","text":"Free-weight flat bench; head, shoulders and buttocks remain on bench; feet supported and fixed. Use a full thumb-around grip. Record belt/wrist wraps; no bench shirt or assistance device."},{"id":"contact","text":"Lower to chest or upper abdomen under control. The bar must visibly stop before pressing; no bounce or heave. Side-oblique view must show contact and elbows."},{"id":"range","text":"At the bottom, the underside of both elbow joints reaches at least the top surface of each shoulder joint. Camera must permit judgment; ambiguous footage is inconclusive."},{"id":"finish","text":"Press to stable extension of both elbows without downward reversal; rack only after completion. Handoff allowed before the start, but any spotter contact during the scored rep invalidates it."}],"discipline":"bench","equipment":["raw-barbell"],"evidence":"Continuous unedited footage showing setup, complete attempt and finish; load markings and total load, date/identity linkage and bodyweight/category attestation must be reviewable. Additional angles may be required. No automated form or identity certification.","id":"bench-standard-draft-1","safety":"Do not attempt a dangerous maximum for a rank. Use conservative loads, appropriate safety equipment and competent spotting. Pain or an unclear camera angle is not a reason to repeat a dangerous lift. Ranking is optional.","status":"draft","title":"MONTE Standard \u2014 Barbell Bench Press","variation":"paused-barbell-bench","version":"draft-1","visualExamples":"Pending qualified review; no fabricated example footage is supplied."}','933fc6699065046f52d553b0114304cb835bc23dcb424e903e3114c51727c2b4','system-draft-seed');
INSERT INTO mw_rulebooks(id,discipline,data,digest,author_id) VALUES('curl-standard-draft-1','curl','{"checks":[{"id":"setup","text":"Straight bar only, supinated closed grip, heels no more than 30 cm from a rigid vertical wall. Head, upper back and buttocks contact the wall; both feet stay planted. No EZ bar or dumbbell substitutions."},{"id":"start","text":"Start motionless, elbows fully extended within the athlete\u2019s natural pain-free range, bar clear of supports. Record total bar-and-plate load."},{"id":"motion","text":"Curl with simultaneous elbow flexion, keeping upper arms near the torso and the three wall contacts. No hip drive, knee dip, torso swing, shoulder thrust, bounce or assistance."},{"id":"finish","text":"Reach full controlled elbow flexion with the bar approaching the shoulders without resting on the torso; pause visibly and lower under control to the start. Side and front-oblique views must allow range and contact assessment."}],"discipline":"curl","equipment":["straight-bar"],"evidence":"Continuous unedited footage showing setup, complete attempt and finish; load markings and total load, date/identity linkage and bodyweight/category attestation must be reviewable. Additional angles may be required. No automated form or identity certification.","id":"curl-standard-draft-1","safety":"Do not attempt a dangerous maximum for a rank. Use conservative loads, appropriate safety equipment and competent spotting. Pain or an unclear camera angle is not a reason to repeat a dangerous lift. Ranking is optional.","status":"draft","title":"MONTE Standard \u2014 Strict Biceps Curl","variation":"wall-strict-straight-bar-curl","version":"draft-1","visualExamples":"Pending qualified review; no fabricated example footage is supplied."}','62f387a0fb6b42eccccf6172ca998ce91864002e009b523ea4f7bc87716dc94c','system-draft-seed');
INSERT INTO mw_rulebooks(id,discipline,data,digest,author_id) VALUES('deadlift-standard-draft-1','deadlift','{"checks":[{"id":"setup","text":"Conventional stance only in this launch draft: hands outside legs, bar starts stationary on floor. Full-size plates with nominal 450 mm diameter; no blocks, deficit, trap bar or sumo comparisons."},{"id":"control","text":"Lift without straps, hitching, supporting the bar on thighs, assistance or intentional downward movement before lockout. Belt and chalk allowed. No supportive suit."},{"id":"finish","text":"Stand erect with hips and knees extended and shoulders in a stable upright position, without exaggerated leaning back."},{"id":"lower","text":"Keep both hands on the bar while returning it under control. Dropping or losing control invalidates the attempt. Footage shows floor, knees, hips and completion."}],"discipline":"deadlift","equipment":["raw-barbell"],"evidence":"Continuous unedited footage showing setup, complete attempt and finish; load markings and total load, date/identity linkage and bodyweight/category attestation must be reviewable. Additional angles may be required. No automated form or identity certification.","id":"deadlift-standard-draft-1","safety":"Do not attempt a dangerous maximum for a rank. Use conservative loads, appropriate safety equipment and competent spotting. Pain or an unclear camera angle is not a reason to repeat a dangerous lift. Ranking is optional.","status":"draft","title":"MONTE Standard \u2014 Barbell Deadlift","variation":"conventional-deadlift","version":"draft-1","visualExamples":"Pending qualified review; no fabricated example footage is supplied."}','5c4fa8ad0c30f149ad6e2e6f134aa12387506e4576e25bbde6c3e02a3b92172b','system-draft-seed');
INSERT INTO mw_rulebooks(id,discipline,data,digest,author_id) VALUES('squat-standard-draft-1','squat','{"checks":[{"id":"setup","text":"Free barbell back squat; high- or low-bar position. Start upright, hips and knees extended, feet planted. No Smith machine, front squat, supportive suit or knee wraps."},{"id":"depth","text":"Hip crease passes below the top of the knee on the same side. Side-oblique view must show hip and knee throughout; an obscured depth is inconclusive, not a pass."},{"id":"control","text":"No bounce off safety supports, double descent, assistance, or loss of control. Belt and non-supportive knee sleeves allowed; record equipment."},{"id":"finish","text":"Return to stable upright position with hips and knees extended before reracking. Spotter contact during the scored repetition invalidates it."}],"discipline":"squat","equipment":["raw-barbell"],"evidence":"Continuous unedited footage showing setup, complete attempt and finish; load markings and total load, date/identity linkage and bodyweight/category attestation must be reviewable. Additional angles may be required. No automated form or identity certification.","id":"squat-standard-draft-1","safety":"Do not attempt a dangerous maximum for a rank. Use conservative loads, appropriate safety equipment and competent spotting. Pain or an unclear camera angle is not a reason to repeat a dangerous lift. Ranking is optional.","status":"draft","title":"MONTE Standard \u2014 Barbell Squat","variation":"barbell-back-squat","version":"draft-1","visualExamples":"Pending qualified review; no fabricated example footage is supplied."}','5671ce141b4a581745f15198775b72cbc8943bc5e53d253645de166be7e0792e','system-draft-seed');
