CREATE TRIGGER mw_result_guard BEFORE INSERT ON mw_results BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM mw_performances p JOIN mw_profiles pr ON pr.id=NEW.profile_id WHERE p.id=NEW.performance_id AND p.athlete_id=NEW.athlete_id AND pr.athlete_id=NEW.athlete_id) THEN RAISE(ABORT,'result-owner-mismatch') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM mw_models m JOIN mw_performances p ON p.id=NEW.performance_id WHERE m.id=NEW.model_id AND m.discipline=p.discipline AND m.rulebook_id=NEW.rulebook_id) THEN RAISE(ABORT,'result-model-mismatch') END;
 SELECT CASE WHEN json_extract(NEW.data,'$.rankId') IS NOT NULL AND (NEW.kind='profile-scenario' OR NOT EXISTS(SELECT 1 FROM mw_publications WHERE kind='model' AND version_id=NEW.model_id) OR NOT EXISTS(SELECT 1 FROM mw_publications WHERE kind='rulebook' AND version_id=NEW.rulebook_id)) THEN RAISE(ABORT,'unapproved-rank-result') END;
 SELECT CASE WHEN NEW.kind<>'profile-scenario' AND COALESCE(json_extract(NEW.data,'$.reviewRevision'),0)<>COALESCE((SELECT MAX(revision) FROM mw_reviews WHERE performance_id=NEW.performance_id),0) THEN RAISE(ABORT,'stale-review-calculation') END;
END;
